// @FIGURE_CODE_BEGIN
/* ─── palette & model ─────────────────────────────────────────────── */
var FIG_TEAL = '#1a8a9a', FIG_TEAL_D = '#0f6c7a', FIG_RED = '#ee2b2b',
    FIG_BLUE = '#0b72c4', FIG_INK = '#222222', FIG_DIM = '#bfc4c9';

var figState = { breakType: 'both', traceX: 5, factorView: 'orig' };
var FIG_HALF = 7.3, FIG_CX = 3;
var FIG_S = 1;

function figF(x) { return (x - 1) / (x - 3); }           // simplified form
var FIG_HX = -1, FIG_HY = figF(-1);                       // hole at (-1, 0.5)

var figContainer = document.getElementById('container');
var figCanvas = document.createElement('canvas');
figCanvas.style.cssText = 'width:100%;height:100%;display:block';
figContainer.appendChild(figCanvas);

var figBranchL = [], figBranchR = [], figChart = null;

/* ─── helpers ─────────────────────────────────────────────────────── */
function PX(v) { return figChart.scales.x.getPixelForValue(v); }
function PY(v) { return figChart.scales.y.getPixelForValue(v); }

function figFont(size, italic, bold) {
  return (italic ? 'italic ' : '') + (bold ? 'bold ' : '') + size + 'px Georgia, "Times New Roman", serif';
}
function figText(ctx, txt, x, y, o) {
  o = o || {};
  ctx.save();
  ctx.font = figFont(o.size || 12, o.italic, o.bold);
  ctx.textAlign = o.align || 'left';
  ctx.textBaseline = o.baseline || 'middle';
  if (o.halo !== false) {
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = o.haloW || 3.5;
    ctx.strokeText(txt, x, y);
  }
  ctx.fillStyle = o.color || FIG_INK;
  ctx.fillText(txt, x, y);
  ctx.restore();
}
function figArrowHead(ctx, x, y, ang, size, color) {
  ctx.save();
  ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-size, size * 0.42);
  ctx.lineTo(-size * 0.7, 0);
  ctx.lineTo(-size, -size * 0.42);
  ctx.closePath();
  ctx.fillStyle = color; ctx.fill();
  ctx.restore();
}
function figRoundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}
function figNum(v) { return (v < 0 ? '\u2212' : '') + Math.abs(v).toFixed(2); }

/* ─── curve sampling ──────────────────────────────────────────────── */
function figRebuildBranches() {
