  ctx.strokeStyle = FIG_INK; ctx.lineWidth = 1.1 * S;
  ctx.beginPath(); ctx.moveTo(fx, cy); ctx.lineTo(fx + fw, cy); ctx.stroke();
  ctx.restore();
  if (suffix) figText(ctx, suffix, fx + fw, cy, { size: size, italic: true, halo: false, color: '#777' });
}

function figDrawTrace(ctx, S) {
  var tx = figState.traceX;
  var nearHole = Math.abs(tx - FIG_HX) < 0.026;
  var holeCase = nearHole && figState.factorView === 'orig';
  var atAsym = Math.abs(tx - 3) < 0.02;
  var y = figF(tx);
  var label, col;

  if (atAsym) {
    label = 'x = 3: undefined';
    col = FIG_RED;
    ctx.save();
    ctx.setLineDash([4 * S, 4 * S]); ctx.strokeStyle = FIG_RED; ctx.lineWidth = 1.2 * S;
    ctx.restore();
    figTraceBox(ctx, PX(3) + 12 * S, PY(0) - 26 * S, label, col, S);
    return;
  }
  if (holeCase) {
    label = 'f(\u22121) is undefined (hole)';
    figTraceBox(ctx, PX(FIG_HX) + 14 * S, PY(FIG_HY) - 24 * S, label, FIG_BLUE, S);
    return;
  }

  var yDraw = Math.max(-6.75, Math.min(6.75, y));
  var off = Math.abs(y) > 6.75;
  var pxv = PX(tx), pyv = PY(yDraw);

  ctx.save();
  ctx.setLineDash([3 * S, 4 * S]);
  ctx.strokeStyle = 'rgba(26,138,154,0.55)'; ctx.lineWidth = 1.2 * S;
  ctx.beginPath(); ctx.moveTo(pxv, PY(0)); ctx.lineTo(pxv, pyv); ctx.stroke();
  ctx.restore();

  ctx.save();
  ctx.beginPath(); ctx.arc(pxv, pyv, 5.2 * S, 0, 6.2832);
  ctx.fillStyle = FIG_TEAL_D; ctx.fill();
  ctx.lineWidth = 1.8 * S; ctx.strokeStyle = '#fff'; ctx.stroke();
  ctx.restore();

  label = '(' + figNum(tx) + ', ' + (off ? (y > 0 ? '+' : '\u2212') + Math.abs(y).toFixed(1) : figNum(y)) + ')';
  col = (Math.abs(y) > 4 || Math.abs(tx - 3) < 0.6) ? FIG_RED : FIG_TEAL_D;
  var bx = pxv + 13 * S, by = pyv - 18 * S;
  if (bx > PX(8.2)) bx = pxv - 13 * S - 78 * S;
  if (by < PY(6.6)) by = pyv + 20 * S;
  figTraceBox(ctx, bx, by, label, col, S);
}

function figTraceBox(ctx, x, y, text, col, S) {
  ctx.save();
  ctx.font = figFont(12 * S, false, true);
  var w = ctx.measureText(text).width + 12 * S, h = 19 * S;
  ctx.globalAlpha = 0.93; ctx.fillStyle = '#fff';
  figRoundRect(ctx, x, y - h / 2, w, h, 4 * S); ctx.fill();
  ctx.globalAlpha = 1; ctx.strokeStyle = col; ctx.lineWidth = 1.2 * S; ctx.stroke();
  ctx.fillStyle = col; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
  ctx.fillText(text, x + 6 * S, y + 0.5 * S);
  ctx.restore();
}

/* ─── chart ───────────────────────────────────────────────────────── */
var figPlugin = {
  id: 'figLayers',
  beforeDatasetsDraw: function (c) { figDrawBackground(c); },
  afterDatasetsDraw: function (c) { figDrawOverlay(c); }
};

function figAspect() {
  var w = figCanvas.clientWidth || figContainer.clientWidth || 600;
  var h = figCanvas.clientHeight || figContainer.clientHeight || 600;
  var xh = FIG_HALF, yh = FIG_HALF;
  if (w > h) xh = FIG_HALF * w / h; else yh = FIG_HALF * h / w;
  return { xmin: FIG_CX - xh, xmax: FIG_CX + xh, ymin: -yh, ymax: yh };
}

var figA0 = figAspect();
figChart = new Chart(figCanvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [
      { data: [], borderColor: FIG_TEAL, borderWidth: 3, pointRadius: 0, tension: 0, fill: false },
      { data: [], borderColor: FIG_TEAL, borderWidth: 3, pointRadius: 0, tension: 0, fill: false }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: 250 },
    layout: { padding: 0 },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { type: 'linear', min: figA0.xmin, max: figA0.xmax, display: false },
      y: { type: 'linear', min: figA0.ymin, max: figA0.ymax, display: false }
    }
  },
  plugins: [figPlugin]
});
figRebuildBranches();
figChart.update('none');
window.__markRendered();

/* ─── resize ──────────────────────────────────────────────────────── */
document.addEventListener('fig-resize', function () {
  var a = figAspect();
  figChart.options.scales.x.min = a.xmin; figChart.options.scales.x.max = a.xmax;
  figChart.options.scales.y.min = a.ymin; figChart.options.scales.y.max = a.ymax;
  figChart.resize();
  figRebuildBranches();
  figChart.update('none');
});

/* ─── control handlers ────────────────────────────────────────────── */
function toggle_breakType(v) {
  figState.breakType = v;
  figChart.update('none');
  figUpdateReadout();
}
function update_traceX(v) {
  figState.traceX = v;
  figChart.update('none');
  figUpdateReadout();
}
function toggle_factorView(v) {
  figState.factorView = v;
  figChart.update('none');
  figUpdateReadout();
}
function figUpdateReadout() {
  var el = document.getElementById('traceReadout');
  if (!el) return;
  var x = figState.traceX, txt;
  if (Math.abs(x - 3) < 0.02) { txt = 'f(3) undefined \u2014 vertical asymptote'; }
  else if (Math.abs(x + 1) < 0.026 && figState.factorView === 'orig') { txt = 'f(\u22121) = 0/0 \u2014 hole (undefined)'; }
  else if (Math.abs(x + 1) < 0.026) { txt = 'after cancelling: f(\u22121) = 0.50'; }
  else { txt = 'f(' + figNum(x) + ') = ' + figF(x).toFixed(2); }
  el.textContent = txt;
  el.style.color = (Math.abs(x - 3) < 0.6) ? FIG_RED : FIG_TEAL_D;
}

/* ─── hover / click ───────────────────────────────────────────────── */
function figHit(e) {
  var r = figCanvas.getBoundingClientRect();
  var mx = e.clientX - r.left, my = e.clientY - r.top;
  var S = FIG_S;
  var dh = Math.hypot(mx - PX(FIG_HX), my - PY(FIG_HY));
  if (dh < 13 * S) return { k: 'hole' };
  if (Math.abs(mx - PX(3)) < 9 * S && my > PY(6.9) && my < PY(-6.9)) return { k: 'asym' };
  var xv = figChart.scales.x.getValueForPixel(mx);
  if (xv > -3.95 && xv < 9.75 && Math.abs(xv - 3) > 0.06) {
    var yv = figF(xv);
    if (Math.abs(yv) < 7 && Math.abs(my - PY(yv)) < 11 * S) return { k: 'curve', x: xv, y: yv };
  }
  return null;
}
figCanvas.addEventListener('mousemove', function (e) {
  var h = figHit(e);
  figCanvas.style.cursor = h ? 'pointer' : 'default';
  if (!h) { hideTooltip(); return; }
  if (h.k === 'hole') showTooltip('Hole at x = \u22121: both sides approach y = 0.5, but that single point is missing.', e);
  else if (h.k === 'asym') showTooltip('Vertical asymptote x = 3: values run to \u2212\u221e on the left, +\u221e on the right.', e);
  else showTooltip('f(' + figNum(h.x) + ') = ' + h.y.toFixed(2), e);
});
figCanvas.addEventListener('mouseleave', hideTooltip);
figCanvas.addEventListener('click', function (e) {
  var h = figHit(e);
  if (!h) return;
  if (h.k === 'hole') showPopup('Removable discontinuity at x = \u22121',
    'The factor (x + 1) appears in both numerator and denominator, so it cancels. The simplified function (x \u2212 1)/(x \u2212 3) is perfectly smooth at x = \u22121 and equals 0.5 there, but the original expression is 0/0, so the point is punched out. Defining f(\u22121) = 0.5 would repair the graph completely.');
  else if (h.k === 'asym') showPopup('Vertical asymptote at x = 3',
    'The factor (x \u2212 3) survives in the denominator, so as x \u2192 3 the denominator shrinks to zero while the numerator stays near 2. Values dive to \u2212\u221e from the left and rocket to +\u221e from the right \u2014 no single number could ever patch this break.');
  else showPopup('The rational function',
    'f(x) = (x \u2212 1)(x + 1) / [(x \u2212 3)(x + 1)] simplifies to (x \u2212 1)/(x \u2212 3) with x \u2260 \u22121. It crosses the x-axis at x = 1 (numerator zero) and flattens toward y = 1 far from the origin.');
});

/* ─── demo step player ────────────────────────────────────────────── */
var FIG_STEPS = [
  { title: 'The whole graph', narration: 'A single rational function drawn in two teal branches. Two things interrupt it: a tiny hollow circle at x = \u22121 and a red dashed line at x = 3.', state: { breakType: 'both', traceX: 5, factorView: 'orig' } },
  { title: 'A single missing point', narration: 'Highlighting the removable discontinuity shows the curve arriving at x = \u22121 from both sides at the same height \u2014 only the one point is punched out.', state: { breakType: 'hole', traceX: -1.4, factorView: 'orig' } },
  { title: 'Why it is removable', narration: 'Cancelling the shared (x + 1) factor gives a function that is perfectly continuous there. Redefining one value would repair the graph entirely.', state: { breakType: 'hole', traceX: -1, factorView: 'cancel' } },
  { title: 'Approaching x = 3 from the left', narration: 'Now drag the trace point toward 3 from the left. The y-value dives past \u22126 and keeps falling \u2014 there is no height to land on.', state: { breakType: 'asym', traceX: 2.9, factorView: 'orig' } },
  { title: 'Approaching x = 3 from the right', narration: 'From the right the value rockets upward instead. Opposite infinities on the two sides mean this break can never be patched by a single point.', state: { breakType: 'asym', traceX: 3.1, factorView: 'orig' } },
  { title: 'Two breaks, two causes', narration: 'The hole comes from a factor that cancels; the asymptote comes from a factor that survives in the denominator. Same graph, two very different failures.', state: { breakType: 'both', traceX: 5, factorView: 'orig' } }
];
var figStep = 0;
function figSetStep(i) {
  figStep = (i + FIG_STEPS.length) % FIG_STEPS.length;
  var s = FIG_STEPS[figStep];
  var b = document.getElementById('breakTypeInput');
  b.value = s.state.breakType; toggle_breakType(s.state.breakType);
  var t = document.getElementById('traceXInput');
  t.value = s.state.traceX;
  document.getElementById('traceXVal').value = (+s.state.traceX).toFixed(2);
  update_traceX(+s.state.traceX);
  var fv = document.getElementById('factorViewInput');
  fv.value = s.state.factorView; toggle_factorView(s.state.factorView);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (figStep + 1) + '/' + FIG_STEPS.length + ' \u00b7 ' + s.title;
}
function nextStep() { figSetStep(figStep + 1); }
function prevStep() { figSetStep(figStep - 1); }
figSetStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
