// @FIGURE_CODE_BEGIN
/* ─── palette & model ─────────────────────────────────────────────── */
var FIG_TEAL = '#1a8a9a', FIG_TEAL_D = '#0f6c7a', FIG_RED = '#ee2b2b',
    FIG_BLUE = '#0b72c4', FIG_INK = '#222222', FIG_DIM = '#bfc4c9';

/* showTrace / showFormula start FALSE so the step-0 render is a clean,
   annotation-for-annotation match of the printed figure. */
var figState = { breakType: 'both', traceX: 5, factorView: 'orig',
                 showTrace: false, showFormula: false };
var figInStep = false;

/* Core plotted field plus a reserved left margin (world units) that holds the
   blue caption OUTSIDE the dotted grid, exactly as in the printed figure. */
var FIG_CORE = { x0: -4.2, x1: 10.2, y0: -7.3, y1: 7.3 };
var FIG_LEFTMARGIN = 4.4;
var FIG_S = 1;
var FIG_YCUT = 9.0;               // sample the branches out to |f| = 9

function figF(x) { return (x - 1) / (x - 3); }           // simplified form
function figXatY(y) { return (3 * y - 1) / (y - 1); }    // inverse of figF
var FIG_HX = -1, FIG_HY = figF(-1);                       // hole at (-1, 0.5)

var figContainer = document.getElementById('container');
var figCanvas = document.createElement('canvas');
figCanvas.style.cssText = 'width:100%;height:100%;display:block';
figContainer.appendChild(figCanvas);

var figBranchL = [], figBranchR = [], figChart = null;

/* ─── helpers ─────────────────────────────────────────────────────── */
function PX(v) { return figChart.scales.x.getPixelForValue(v); }
function PY(v) { return figChart.scales.y.getPixelForValue(v); }

function figFont(size, italic, bold) {
  return (italic ? 'italic ' : '') + (bold ? 'bold ' : '') + size + 'px Georgia, "Times New Roman", serif';
}
function figText(ctx, txt, x, y, o) {
  o = o || {};
  ctx.save();
  ctx.font = figFont(o.size || 12, o.italic, o.bold);
  ctx.textAlign = o.align || 'left';
  ctx.textBaseline = o.baseline || 'middle';
  if (o.halo !== false) {
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = o.haloW || 3.5;
    ctx.strokeText(txt, x, y);
  }
  ctx.fillStyle = o.color || FIG_INK;
  ctx.fillText(txt, x, y);
  ctx.restore();
}
function figArrowHead(ctx, x, y, ang, size, color) {
  ctx.save();
  ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-size, size * 0.42);
  ctx.lineTo(-size * 0.7, 0);
  ctx.lineTo(-size, -size * 0.42);
  ctx.closePath();
  ctx.fillStyle = color; ctx.fill();
  ctx.restore();
}
function figRoundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}
function figNum(v) { return (v < 0 ? '\u2212' : '') + Math.abs(v).toFixed(2); }

/* ─── curve sampling ──────────────────────────────────────────────── */
function figRebuildBranches() {
  var xs = figChart.scales.x;
  var loL = -3.75;
  var hiR = Math.min(xs.max - 0.4, 9.75);
  var endL = figXatY(-FIG_YCUT);      // 2.800  — tucked against the asymptote
  var startR = figXatY(FIG_YCUT);     // 3.250  — tucked against the asymptote
  var i, t, x, N = 460;
  figBranchL.length = 0; figBranchR.length = 0;
  for (i = 0; i <= N; i++) {
    t = i / N;
    x = loL + (endL - loL) * (1 - Math.pow(1 - t, 3));   // dense near asymptote
    figBranchL.push({ x: x, y: figF(x) });
  }
  for (i = 0; i <= N; i++) {
    t = i / N;
    x = startR + (hiR - startR) * Math.pow(t, 3);        // dense near asymptote
    figBranchR.push({ x: x, y: figF(x) });
  }
  if (figChart.data && figChart.data.datasets.length) {
    var bw = 3.5 * FIG_S;
    figChart.data.datasets[0].data = figBranchL.slice();
    figChart.data.datasets[1].data = figBranchR.slice();
    figChart.data.datasets[0].borderWidth = bw;
    figChart.data.datasets[1].borderWidth = bw;
  }
}

/* ─── background layer: grid, axes, ticks, asymptote ──────────────── */
function figDrawBackground(chart) {
  var ctx = chart.ctx, a = chart.chartArea;
  FIG_S = Math.max(0.55, Math.min(1.7, Math.min(a.width, a.height) / 470));
  var S = FIG_S, i, j, t;

  /* dotted field: true dot markers, matching the printed dotted grid */
  var gxA = -3.5, gxB = 9.5, gyA = -6.5, gyB = 6.5;
  var d = Math.max(1, 1.1 * Math.min(1.3, S));
  ctx.save();
  ctx.fillStyle = '#bcbcbc';
  for (i = -3; i <= 9; i++) {
    var gpx = PX(i);
    for (t = gyA; t <= gyB + 1e-6; t += 0.25) ctx.fillRect(gpx - d / 2, PY(t) - d / 2, d, d);
  }
  for (j = -6; j <= 6; j++) {
    var gpy = PY(j);
    for (t = gxA; t <= gxB + 1e-6; t += 0.25) ctx.fillRect(PX(t) - d / 2, gpy - d / 2, d, d);
  }
  ctx.restore();

  // horizontal end-behaviour guide (only while the asymptote is the focus)
  if (figState.breakType === 'asym') {
    ctx.save();
    ctx.setLineDash([6 * S, 5 * S]); ctx.lineWidth = 1.3 * S; ctx.strokeStyle = '#9aa2a8';
    ctx.beginPath(); ctx.moveTo(PX(3.15), PY(1)); ctx.lineTo(PX(9.4), PY(1)); ctx.stroke();
    ctx.restore();
    figText(ctx, 'y = 1', PX(9.35), PY(1) + 11 * S, { size: 11 * S, color: '#7d858b', align: 'right', italic: true });
  }

  // ── axis extents: keep the arrow tip AND the italic label fully inside ──
  var tipPx = Math.min(PX(10.1), a.right - 34 * S);
  tipPx = Math.max(tipPx, PX(9.7));
  var tipPy = Math.max(PY(7.15), a.top + 24 * S);
  tipPy = Math.min(tipPy, PY(6.9));
  var axLo = Math.max(chart.scales.x.min + 0.1, -4.05);
  var ayLo = Math.max(chart.scales.y.min + 0.1, -7.15);

  ctx.save();
  ctx.strokeStyle = FIG_INK; ctx.lineWidth = 1.5 * S; ctx.setLineDash([]);
  ctx.beginPath(); ctx.moveTo(PX(axLo), PY(0)); ctx.lineTo(tipPx, PY(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(PX(0), PY(ayLo)); ctx.lineTo(PX(0), tipPy); ctx.stroke();
  ctx.restore();
  figArrowHead(ctx, tipPx, PY(0), 0, 9 * S, FIG_INK);
  figArrowHead(ctx, PX(0), tipPy, -Math.PI / 2, 9 * S, FIG_INK);
  figText(ctx, 'x', Math.min(tipPx + 13 * S, a.right - 7 * S), PY(0) + 11 * S, { size: 15 * S, italic: true, align: 'center' });
  figText(ctx, 'y', PX(0) - 12 * S, Math.max(tipPy + 2 * S, a.top + 9 * S), { size: 15 * S, italic: true, align: 'right' });

  // ticks + labels
  ctx.save();
  ctx.strokeStyle = FIG_INK; ctx.lineWidth = 1.2 * S;
  for (i = -3; i <= 9; i++) {
    ctx.beginPath(); ctx.moveTo(PX(i), PY(0) - 3.5 * S); ctx.lineTo(PX(i), PY(0) + 3.5 * S); ctx.stroke();
  }
  for (i = -6; i <= 6; i++) {
    ctx.beginPath(); ctx.moveTo(PX(0) - 3.5 * S, PY(i)); ctx.lineTo(PX(0) + 3.5 * S, PY(i)); ctx.stroke();
  }
  ctx.restore();
  var xt = [-3, -1, 1, 3, 5, 7, 9];
  for (i = 0; i < xt.length; i++) {
    var v = xt[i];
    // "3" sits a row LOWER (never sideways) so it clears the red dashed line
    var dy = (v === 3) ? 27 * S : 14 * S;
    figText(ctx, (v < 0 ? '\u2212' : '') + Math.abs(v), PX(v), PY(0) + dy,
      { size: 13 * S, align: 'center', haloW: (v === 3 ? 5.5 : 3.5) });
  }
  var yt = [-6, -4, -2, 2, 4, 6];
  for (i = 0; i < yt.length; i++) {
    figText(ctx, (yt[i] < 0 ? '\u2212' : '') + Math.abs(yt[i]), PX(0) - 8 * S, PY(yt[i]),
      { size: 13 * S, align: 'right' });
  }

  // red dashed vertical asymptote — longer dashes, heavier stroke
  var asymHot = figState.breakType !== 'hole';
  ctx.save();
  ctx.setLineDash([15 * S, 9 * S]);
  ctx.lineWidth = (figState.breakType === 'asym' ? 4.0 : 3.2) * S;
  ctx.strokeStyle = asymHot ? FIG_RED : FIG_DIM;
  ctx.beginPath(); ctx.moveTo(PX(3), PY(6.9)); ctx.lineTo(PX(3), PY(-6.9)); ctx.stroke();
  ctx.restore();
  if (figState.breakType === 'asym') {
    figArrowHead(ctx, PX(3), PY(7.0), -Math.PI / 2, 8 * S, FIG_RED);
    figArrowHead(ctx, PX(3), PY(-7.0), Math.PI / 2, 8 * S, FIG_RED);
  }
}

/* ─── branch arrowheads (horizontal ends + asymptote ends) ────────── */
function figBranchArrows(ctx, S) {
  var ys = figChart.scales.y;
  var i, p0, p1;

  // far-left tail of the left branch
  if (figBranchL.length > 2) {
    p0 = figBranchL[0]; p1 = figBranchL[1];
    figArrowHead(ctx, PX(p0.x), PY(p0.y),
      Math.atan2(PY(p0.y) - PY(p1.y), PX(p0.x) - PX(p1.x)), 9.5 * S, FIG_TEAL);
  }
  // far-right tail of the right branch
  if (figBranchR.length > 2) {
    p0 = figBranchR[figBranchR.length - 1]; p1 = figBranchR[figBranchR.length - 2];
    figArrowHead(ctx, PX(p0.x), PY(p0.y),
      Math.atan2(PY(p0.y) - PY(p1.y), PX(p0.x) - PX(p1.x)), 9.5 * S, FIG_TEAL);
  }

  // downward tip of the left branch — placed right at the frame edge
  var yDn = Math.max(ys.min + 0.30, -(FIG_YCUT - 0.3));
  var xDn = figXatY(yDn), xDn2 = figXatY(yDn * 0.78);
  figArrowHead(ctx, PX(xDn), PY(yDn),
    Math.atan2(PY(yDn) - PY(yDn * 0.78), PX(xDn) - PX(xDn2)), 9.5 * S, FIG_TEAL);

  // upward tip of the right branch
  var yUp = Math.min(ys.max - 0.30, FIG_YCUT - 0.3);
  var xUp = figXatY(yUp), xUp2 = figXatY(yUp * 0.78);
  figArrowHead(ctx, PX(xUp), PY(yUp),
    Math.atan2(PY(yUp) - PY(yUp * 0.78), PX(xUp) - PX(xUp2)), 9.5 * S, FIG_TEAL);
}

/* ─── overlay layer: markers, labels, trace ───────────────────────── */
function figDrawOverlay(chart) {
  var ctx = chart.ctx, a = chart.chartArea, S = FIG_S;

  figBranchArrows(ctx, S);

  var hx = PX(FIG_HX), hy = PY(FIG_HY);
  var holeHot = figState.breakType !== 'asym';

  // ghost of the "filled in" point (cancelled view)
  if (figState.factorView === 'cancel') {
    ctx.save();
    ctx.globalAlpha = 0.35; ctx.fillStyle = FIG_TEAL;
    ctx.beginPath(); ctx.arc(hx, hy, 6.5 * S, 0, 6.2832); ctx.fill();
    ctx.restore();
  }

  // open circle (removable discontinuity)
  if (figState.breakType === 'hole') {
    ctx.save(); ctx.globalAlpha = 0.18; ctx.fillStyle = FIG_BLUE;
    ctx.beginPath(); ctx.arc(hx, hy, 13 * S, 0, 6.2832); ctx.fill(); ctx.restore();
  }
  ctx.save();
  ctx.beginPath();
  ctx.arc(hx, hy, (figState.breakType === 'hole' ? 6.6 : 5.4) * S, 0, 6.2832);
  ctx.fillStyle = '#ffffff'; ctx.fill();
  ctx.lineWidth = (figState.breakType === 'hole' ? 3.2 : 2.5) * S;
  ctx.strokeStyle = holeHot ? FIG_TEAL : FIG_DIM;
  ctx.stroke();
  ctx.restore();

  /* ── blue annotation, in the LEFT MARGIN outside the dotted field ── */
  var annCol = holeHot ? FIG_BLUE : FIG_DIM;
  var lines = ['Removable', 'discontinuity', 'at x = \u22121'];
  var size = 13.5 * S;
  var leftEdge = a.left + 4 * S;
  var avail = Math.max(48, PX(-3.7) - leftEdge - 4 * S);
  ctx.save();
  ctx.font = figFont(size, false);
  var wmax = 0, k;
  for (k = 0; k < lines.length; k++) wmax = Math.max(wmax, ctx.measureText(lines[k]).width);
  ctx.restore();
  if (wmax > avail) { size *= avail / wmax; wmax = avail; }
  var lh = size * 1.18;
  var tx0 = leftEdge, ty0 = PY(4.3);
  figText(ctx, lines[0], tx0, ty0, { size: size, color: annCol });
  figText(ctx, lines[1], tx0, ty0 + lh, { size: size, color: annCol });
  figText(ctx, lines[2], tx0, ty0 + 2 * lh, { size: size, color: annCol, italic: true });

  // thin leader arrow from the caption to the open circle
  var ax0 = tx0 + wmax * 0.55, ay0 = ty0 + 2 * lh + 0.75 * lh;
  var ax1 = hx - 10 * S, ay1 = hy - 11 * S;
  ctx.save();
  ctx.strokeStyle = holeHot ? '#333' : FIG_DIM; ctx.lineWidth = 1.2 * S;
  ctx.beginPath(); ctx.moveTo(ax0, ay0); ctx.lineTo(ax1, ay1); ctx.stroke();
  ctx.restore();
  figArrowHead(ctx, ax1, ay1, Math.atan2(ay1 - ay0, ax1 - ax0), 7 * S, holeHot ? '#333' : FIG_DIM);

  // red caption
  figText(ctx, 'Vertical asymptote at x = 3', PX(3.35), PY(-6.95),
    { size: 13.5 * S, color: figState.breakType !== 'hole' ? FIG_RED : FIG_DIM, italic: true });

  // formula caption — revealed only after the student engages
  if (figState.showFormula) figDrawFormula(ctx, PX(6.9), PY(5.95), S);

  // trace point — likewise hidden in the default (step 0) view
  if (figState.showTrace) figDrawTrace(ctx, S);
}

function figDrawFormula(ctx, cx, cy, S) {
  var size = 13 * S;
  var lhs = 'f(x) =';
  var num, den, suffix;
  if (figState.factorView === 'orig') { num = '(x \u2212 1)(x + 1)'; den = '(x \u2212 3)(x + 1)'; suffix = ''; }
  else { num = 'x \u2212 1'; den = 'x \u2212 3'; suffix = ',  x \u2260 \u22121'; }
  ctx.save();
  ctx.font = figFont(size, true);
  var lw = ctx.measureText(lhs).width;
  var nw = ctx.measureText(num).width, dw = ctx.measureText(den).width;
  var fw = Math.max(nw, dw);
  var sw = suffix ? ctx.measureText(suffix).width : 0;
  var total = lw + 7 * S + fw + sw;
  var x0 = cx - total / 2;
  var padX = 7 * S, padY = 6 * S, boxH = size * 2.6 + padY;
  ctx.globalAlpha = 0.92; ctx.fillStyle = '#ffffff';
  figRoundRect(ctx, x0 - padX, cy - boxH / 2, total + 2 * padX, boxH, 4 * S);
  ctx.fill();
  ctx.globalAlpha = 1; ctx.strokeStyle = '#dfe3e6'; ctx.lineWidth = 1; ctx.stroke();
  ctx.restore();

  figText(ctx, lhs, x0, cy, { size: size, italic: true, halo: false, color: FIG_INK });
  var fx = x0 + lw + 7 * S;
  figText(ctx, num, fx + fw / 2, cy - size * 0.72, { size: size, italic: true, align: 'center', halo: false, color: FIG_TEAL_D });
  figText(ctx, den, fx + fw / 2, cy + size * 0.78, { size: size, italic: true, align: 'center', halo: false, color: FIG_TEAL_D });
  ctx.save();
  ctx.strokeStyle = FIG_INK; ctx.lineWidth = 1.1 * S;
  ctx.beginPath(); ctx.moveTo(fx, cy); ctx.lineTo(fx + fw, cy); ctx.stroke();
  ctx.restore();
  if (suffix) figText(ctx, suffix, fx + fw, cy, { size: size, italic: true, halo: false, color: '#777' });
}

function figDrawTrace(ctx, S) {
  var tx = figState.traceX;
  var nearHole = Math.abs(tx - FIG_HX) < 0.026;
  var holeCase = nearHole && figState.factorView === 'orig';
  var atAsym = Math.abs(tx - 3) < 0.02;
  var y = figF(tx);
  var label, col;

  if (atAsym) {
    figTraceBox(ctx, PX(3) + 14 * S, PY(0) - 30 * S, 'x = 3: undefined', FIG_RED, S);
    return;
  }
  if (holeCase) {
    figTraceBox(ctx, PX(FIG_HX) + 14 * S, PY(FIG_HY) - 24 * S,
      'f(\u22121) is undefined (hole)', FIG_BLUE, S);
    return;
  }

  var yDraw = Math.max(-6.75, Math.min(6.75, y));
  var off = Math.abs(y) > 6.75;
  var pxv = PX(tx), pyv = PY(yDraw);

  ctx.save();
  ctx.setLineDash([3 * S, 4 * S]);
  ctx.strokeStyle = 'rgba(26,138,154,0.55)'; ctx.lineWidth = 1.2 * S;
  ctx.beginPath(); ctx.moveTo(pxv, PY(0)); ctx.lineTo(pxv, pyv); ctx.stroke();
  ctx.restore();

  ctx.save();
  ctx.beginPath(); ctx.arc(pxv, pyv, 5.2 * S, 0, 6.2832);
  ctx.fillStyle = FIG_TEAL_D; ctx.fill();
  ctx.lineWidth = 1.8 * S; ctx.strokeStyle = '#fff'; ctx.stroke();
  ctx.restore();

  label = '(' + figNum(tx) + ', ' + (off ? (y > 0 ? '+' : '\u2212') + Math.abs(y).toFixed(1) : figNum(y)) + ')';
  col = (Math.abs(y) > 4 || Math.abs(tx - 3) < 0.6) ? FIG_RED : FIG_TEAL_D;
  var bx = pxv + 13 * S, by = pyv - 18 * S;
  if (bx > PX(8.0)) bx = pxv - 13 * S - 82 * S;
  if (by < PY(6.6)) by = pyv + 20 * S;
  figTraceBox(ctx, bx, by, label, col, S);
}

function figTraceBox(ctx, x, y, text, col, S) {
  ctx.save();
  ctx.font = figFont(12 * S, false, true);
  var w = ctx.measureText(text).width + 12 * S, h = 19 * S;
  ctx.globalAlpha = 0.93; ctx.fillStyle = '#fff';
  figRoundRect(ctx, x, y - h / 2, w, h, 4 * S); ctx.fill();
  ctx.globalAlpha = 1; ctx.strokeStyle = col; ctx.lineWidth = 1.2 * S; ctx.stroke();
  ctx.fillStyle = col; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
  ctx.fillText(text, x + 6 * S, y + 0.5 * S);
  ctx.restore();
}

/* ─── chart ───────────────────────────────────────────────────────── */
var figPlugin = {
  id: 'figLayers',
  beforeDatasetsDraw: function (c) { figDrawBackground(c); },
  afterDatasetsDraw: function (c) { figDrawOverlay(c); }
};

function figAspect() {
  var w = figCanvas.clientWidth || figContainer.clientWidth || 700;
  var h = figCanvas.clientHeight || figContainer.clientHeight || 520;
  var coreW = FIG_CORE.x1 - FIG_CORE.x0, coreH = FIG_CORE.y1 - FIG_CORE.y0;
  var totalW = coreW + FIG_LEFTMARGIN;
  var unit = Math.min(w / totalW, h / coreH);
  var visW = w / unit, visH = h / unit;
  var exX = Math.max(0, visW - totalW), exY = Math.max(0, visH - coreH);
  return {
    xmin: FIG_CORE.x0 - FIG_LEFTMARGIN - exX / 2,
    xmax: FIG_CORE.x1 + exX / 2,
    ymin: FIG_CORE.y0 - exY / 2,
    ymax: FIG_CORE.y1 + exY / 2
  };
}

var figA0 = figAspect();
figChart = new Chart(figCanvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [
      { data: [], borderColor: FIG_TEAL, borderWidth: 3.5, pointRadius: 0, tension: 0, fill: false, borderCapStyle: 'round', borderJoinStyle: 'round' },
      { data: [], borderColor: FIG_TEAL, borderWidth: 3.5, pointRadius: 0, tension: 0, fill: false, borderCapStyle: 'round', borderJoinStyle: 'round' }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: 250 },
    layout: { padding: 0 },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { type: 'linear', min: figA0.xmin, max: figA0.xmax, display: false },
      y: { type: 'linear', min: figA0.ymin, max: figA0.ymax, display: false }
    }
  },
  plugins: [figPlugin]
});
figRebuildBranches();
figChart.update('none');
window.__markRendered();

/* ─── resize ──────────────────────────────────────────────────────── */
document.addEventListener('fig-resize', function () {
  var a = figAspect();
  figChart.options.scales.x.min = a.xmin; figChart.options.scales.x.max = a.xmax;
  figChart.options.scales.y.min = a.ymin; figChart.options.scales.y.max = a.ymax;
  figChart.resize();
  figRebuildBranches();
  figChart.update('none');
});

/* ─── control handlers ────────────────────────────────────────────── */
function figReveal() {
  if (figInStep) return;               // step player controls its own visibility
  figState.showTrace = true;
  figState.showFormula = true;
}
function toggle_breakType(v) {
  figState.breakType = v;
  figReveal();
  figChart.update('none');
  figUpdateReadout();
}
function update_traceX(v) {
  figState.traceX = v;
  figReveal();
  figChart.update('none');
  figUpdateReadout();
}
function toggle_factorView(v) {
  figState.factorView = v;
  figReveal();
  figChart.update('none');
  figUpdateReadout();
}
function figUpdateReadout() {
  var el = document.getElementById('traceReadout');
  if (!el) return;
  if (!figState.showTrace) {
    el.textContent = 'Move the trace slider to probe the function.';
    el.style.color = '#888';
    return;
  }
  var x = figState.traceX, txt;
  if (Math.abs(x - 3) < 0.02) { txt = 'f(3) undefined \u2014 vertical asymptote'; }
  else if (Math.abs(x + 1) < 0.026 && figState.factorView === 'orig') { txt = 'f(\u22121) = 0/0 \u2014 hole (undefined)'; }
  else if (Math.abs(x + 1) < 0.026) { txt = 'after cancelling: f(\u22121) = 0.50'; }
  else { txt = 'f(' + figNum(x) + ') = ' + figF(x).toFixed(2); }
  el.textContent = txt;
  el.style.color = (Math.abs(x - 3) < 0.6) ? FIG_RED : FIG_TEAL_D;
}

/* ─── hover / click ───────────────────────────────────────────────── */
function figHit(e) {
  var r = figCanvas.getBoundingClientRect();
  var mx = e.clientX - r.left, my = e.clientY - r.top;
  var S = FIG_S;
  var dh = Math.hypot(mx - PX(FIG_HX), my - PY(FIG_HY));
  if (dh < 13 * S) return { k: 'hole' };
  if (Math.abs(mx - PX(3)) < 9 * S && my > PY(6.9) && my < PY(-6.9)) return { k: 'asym' };
  var xv = figChart.scales.x.getValueForPixel(mx);
  if (xv > -3.85 && xv < 9.8 && Math.abs(xv - 3) > 0.06) {
    var yv = figF(xv);
    if (Math.abs(yv) < 7.2 && Math.abs(my - PY(yv)) < 11 * S) return { k: 'curve', x: xv, y: yv };
  }
  return null;
}
figCanvas.addEventListener('mousemove', function (e) {
  var h = figHit(e);
  figCanvas.style.cursor = h ? 'pointer' : 'default';
  if (!h) { hideTooltip(); return; }
  if (h.k === 'hole') showTooltip('Hole at x = \u22121: both sides approach y = 0.5, but that single point is missing.', e);
  else if (h.k === 'asym') showTooltip('Vertical asymptote x = 3: values run to \u2212\u221e on the left, +\u221e on the right.', e);
  else showTooltip('f(' + figNum(h.x) + ') = ' + h.y.toFixed(2), e);
});
figCanvas.addEventListener('mouseleave', hideTooltip);
figCanvas.addEventListener('click', function (e) {
  var h = figHit(e);
  if (!h) return;
  if (h.k === 'hole') showPopup('Removable discontinuity at x = \u22121',
    'The factor (x + 1) appears in both numerator and denominator, so it cancels. The simplified function (x \u2212 1)/(x \u2212 3) is perfectly smooth at x = \u22121 and equals 0.5 there, but the original expression is 0/0, so the point is punched out. Defining f(\u22121) = 0.5 would repair the graph completely.');
  else if (h.k === 'asym') showPopup('Vertical asymptote at x = 3',
    'The factor (x \u2212 3) survives in the denominator, so as x \u2192 3 the denominator shrinks to zero while the numerator stays near 2. Values dive to \u2212\u221e from the left and rocket to +\u221e from the right \u2014 no single number could ever patch this break.');
  else showPopup('The rational function',
    'f(x) = (x \u2212 1)(x + 1) / [(x \u2212 3)(x + 1)] simplifies to (x \u2212 1)/(x \u2212 3) with x \u2260 \u22121. It crosses the x-axis at x = 1 (numerator zero) and flattens toward y = 1 far from the origin.');
});

/* ─── demo step player ────────────────────────────────────────────── */
var FIG_STEPS = [
  { title: 'The whole graph', narration: 'A single rational function drawn in two teal branches. Two things interrupt it: a tiny hollow circle at x = \u22121 and a red dashed line at x = 3.', state: { breakType: 'both', traceX: 5, factorView: 'orig' }, show: false },
  { title: 'A single missing point', narration: 'Highlighting the removable discontinuity shows the curve arriving at x = \u22121 from both sides at the same height \u2014 only the one point is punched out.', state: { breakType: 'hole', traceX: -1.4, factorView: 'orig' }, show: true },
